-- ============================================
-- LUMA — Enrichissement Thématique 2 (Rendez-vous amoureux) : scénarios longs
-- ============================================

update scenarios set content = '{"characters": {"date": "ton date"}, "start_node": "n1", "nodes": {"n1": {"speaker": "date", "text": "Dinner was great. Want to keep the night going? There''s a nice bar nearby.", "text_fr": "Le dîner était excellent. Tu veux continuer la soirée ? Il y a un bon bar pas loin.", "choices": [{"text": "I''d love that.", "next": "n2"}, {"text": "How about a walk instead? It''s such a nice evening.", "next": "n2b"}, {"text": "Honestly, I''m a bit tired, but I don''t want the night to end either.", "next": "n2c"}]}, "n2": {"speaker": "date", "text": "Great, this place has amazing live music too.", "text_fr": "Génial, cet endroit a aussi une super musique live.", "choices": [{"text": "Perfect, I love live music.", "next": "n3"}]}, "n2b": {"speaker": "date", "text": "I love that idea, let''s walk by the river.", "text_fr": "J''adore l''idée, marchons le long de la rivière.", "choices": [{"text": "Sounds perfect.", "next": "n3"}]}, "n2c": {"speaker": "date", "text": "How about we just grab a quiet coffee then? No pressure.", "text_fr": "Et si on prenait juste un café tranquille alors ? Sans pression.", "choices": [{"text": "That sounds perfect, actually.", "next": "n3"}]}, "n3": {"speaker": "date", "text": "So, can I be honest about something?", "text_fr": "Je peux être honnête sur quelque chose ?", "choices": [{"text": "Of course, what''s up?", "next": "n4"}, {"text": "That sounds serious, is everything okay?", "next": "n4b"}]}, "n4": {"speaker": "date", "text": "I was really nervous about tonight, but I''m glad I came.", "text_fr": "J''étais vraiment nerveux(se) pour ce soir, mais je suis content(e) d''être venu(e).", "choices": [{"text": "I was nervous too, honestly. This has been really great though.", "next": "n5"}, {"text": "You didn''t seem nervous at all!", "next": "n5b"}]}, "n4b": {"speaker": "date", "text": "Nothing bad, don''t worry — I just wanted to say I''m really enjoying this.", "text_fr": "Rien de grave, ne t''inquiète pas — je voulais juste dire que je passe un très bon moment.", "choices": [{"text": "Me too, more than I expected honestly.", "next": "n5"}]}, "n5": {"speaker": "date", "text": "I''m really glad we''re both being honest.", "text_fr": "Je suis vraiment content(e) qu''on soit tous les deux honnêtes.", "choices": [{"text": "Me too. I don''t want tonight to end.", "next": "n6"}]}, "n5b": {"speaker": "date", "text": "Ha, good acting then! But seriously, this has been great.", "text_fr": "Ha, bonne comédie alors ! Mais sérieusement, c''était génial.", "choices": [{"text": "It really has.", "next": "n6"}]}, "n6": {"speaker": "date", "text": "Should we make this a regular thing? Like, officially?", "text_fr": "On devrait faire de ça une habitude ? Genre, officiellement ?", "choices": [{"text": "I''d really like that.", "next": "end_official"}, {"text": "Let''s take it one date at a time, but I''m definitely interested.", "next": "end_slow"}]}, "end_official": {"speaker": "date", "text": "I really hope this isn''t the last time. So... officially seeing each other?", "text_fr": "J''espère vraiment que ce n''est pas la dernière fois. Alors... officiellement ensemble ?", "end": true, "ending_label": "Relation officialisée 💑"}, "end_slow": {"speaker": "date", "text": "I like that, no rush. But I definitely want a next date.", "text_fr": "J''aime ça, pas de précipitation. Mais je veux clairement un prochain rendez-vous.", "end": true, "ending_label": "Belle suite en douceur 🌙"}}}'::jsonb, is_playable = true
where title = 'Un date qui évolue sur toute une soirée'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"friend": "Jordan (ami·e du date)", "date": "ton date"}, "start_node": "n1", "nodes": {"n1": {"speaker": "date", "text": "Everyone, this is the person I''ve been telling you about!", "text_fr": "Tout le monde, voici la personne dont je vous ai parlé !", "choices": [{"text": "Hi everyone, great to finally meet you all!", "next": "n2"}, {"text": "(feel a bit nervous, but smile and wave)", "next": "n2b"}]}, "n2": {"speaker": "friend", "text": "So, how did you two actually meet?", "text_fr": "Alors, comment vous vous êtes vraiment rencontrés ?", "choices": [{"text": "Actually, it''s a pretty funny story...", "next": "n3"}, {"text": "We met through a dating app, nothing too exciting!", "next": "n3b"}]}, "n2b": {"speaker": "date", "text": "They''re all really friendly, don''t worry.", "text_fr": "Ils sont tous très sympas, ne t''inquiète pas.", "choices": [{"text": "I can tell, thanks for the reassurance.", "next": "n3"}]}, "n3": {"speaker": "friend", "text": "Now I have to hear this!", "text_fr": "Maintenant il faut que j''entende ça !", "choices": [{"text": "(tell the story with enthusiasm)", "next": "n4"}]}, "n3b": {"speaker": "friend", "text": "Ha, well, whatever works!", "text_fr": "Ha, tant que ça marche !", "choices": [{"text": "Exactly!", "next": "n4"}]}, "n4": {"speaker": "friend", "text": "One of your friends is asking a bit of a pointed question — \"So, are you two serious?\"", "text_fr": "Un de tes amis pose une question un peu directe — \"Alors, c''est sérieux entre vous deux ?\"", "choices": [{"text": "We''re taking it one step at a time, but yes, it feels serious.", "next": "n5"}, {"text": "(look at your date, unsure how to answer)", "next": "n5b"}]}, "n5": {"speaker": "date", "text": "(smiles) I like the sound of that.", "text_fr": "(sourit) J''aime bien ce que j''entends.", "choices": [{"text": "I meant every word.", "next": "n6"}]}, "n5b": {"speaker": "date", "text": "I think we''re figuring that out together, and that''s okay.", "text_fr": "Je pense qu''on est en train de le découvrir ensemble, et c''est bien comme ça.", "choices": [{"text": "That''s exactly how I feel too.", "next": "n6"}]}, "n6": {"speaker": "friend", "text": "Well, I can already tell you''re a good match for them.", "text_fr": "En tout cas, je vois déjà que vous allez bien ensemble.", "choices": [{"text": "That means a lot, thank you.", "next": "end_approved"}, {"text": "I hope I can live up to that!", "next": "end_humble"}]}, "end_approved": {"speaker": "date", "text": "See, I told you they''d love you.", "text_fr": "Tu vois, je t''avais dit qu''ils t''adoreraient.", "end": true, "ending_label": "Approuvé par les amis 👍"}, "end_humble": {"speaker": "date", "text": "You already have, trust me.", "text_fr": "C''est déjà le cas, crois-moi.", "end": true, "ending_label": "Intégration réussie dans le groupe 🤗"}}}'::jsonb, is_playable = true
where title = 'Rencontrer les amis de l''autre'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));

update scenarios set content = '{"characters": {"partner": "ton/ta partenaire"}, "start_node": "n1", "nodes": {"n1": {"speaker": "partner", "text": "It''s been a few months now... I feel like I need to tell you something.", "text_fr": "Ça fait quelques mois maintenant... j''ai besoin de te dire quelque chose.", "choices": [{"text": "You can tell me anything.", "next": "n2"}, {"text": "(feel a little nervous) Is everything okay between us?", "next": "n2b"}]}, "n2": {"speaker": "partner", "text": "I think... I think I''m falling in love with you.", "text_fr": "Je crois... je crois que je tombe amoureux/amoureuse de toi.", "choices": [{"text": "I feel exactly the same way.", "next": "n3"}, {"text": "I really care about you, but I need a bit more time.", "next": "n3b"}]}, "n2b": {"speaker": "partner", "text": "Everything''s great, actually — that''s what I want to tell you about.", "text_fr": "Tout va très bien, en fait — c''est ce que je veux te dire.", "choices": [{"text": "Okay, that''s a relief, go on.", "next": "n2"}]}, "n3": {"speaker": "partner", "text": "I was so nervous to say that, but I''m so happy right now.", "text_fr": "J''étais si nerveux/nerveuse de dire ça, mais je suis tellement heureux/heureuse là.", "choices": [{"text": "How long have you felt this way?", "next": "n4"}]}, "n3b": {"speaker": "partner", "text": "Thank you for being honest with me, that means a lot.", "text_fr": "Merci d''être honnête avec moi, ça compte beaucoup.", "choices": [{"text": "I hope you know it''s not a no, just not yet.", "next": "n4b"}]}, "n4": {"speaker": "partner", "text": "Honestly, for weeks now — I just didn''t know how to say it.", "text_fr": "Honnêtement, depuis des semaines — je ne savais juste pas comment le dire.", "choices": [{"text": "I''ve felt it for a while too, I was just waiting for the right moment.", "next": "end_mutual"}]}, "n4b": {"speaker": "partner", "text": "I understand completely, and I''m not going anywhere.", "text_fr": "Je comprends totalement, et je ne vais nulle part.", "choices": [{"text": "That means more to me than you know.", "next": "end_patient"}]}, "end_mutual": {"speaker": "partner", "text": "We really were on the same page this whole time.", "text_fr": "On était vraiment sur la même longueur d''onde depuis le début.", "end": true, "ending_label": "Amour partagé 💕"}, "end_patient": {"speaker": "partner", "text": "Good things are worth waiting for, and I believe we''re one of them.", "text_fr": "Les bonnes choses valent la peine d''attendre, et je crois qu''on en fait partie.", "end": true, "ending_label": "Patience et confiance récompensées 💙"}}}'::jsonb, is_playable = true
where title = 'Une déclaration à un moment clé'
  and theme_id = (select id from scenario_themes where position = 2 and language_id = (select id from languages where code = 'en'));
